class Solution:
    def largestPathValue(self, colors: str, edges: list[list[int]]) -> int:
        n = len(colors)
        g = [[] for _ in range(n)]
        for a, b in edges:
            g[a].append(b)
        state = [0] * n
        memo = [[0] * 26 for _ in range(n)]
        def dfs(u):
            if state[u] == 1:
                return None
            if state[u] == 2:
                return memo[u]
            state[u] = 1
            best = [0] * 26
            for v in g[u]:
                got = dfs(v)
                if got is None:
                    return None
                for c in range(26):
                    best[c] = max(best[c], got[c])
            best[ord(colors[u]) - 97] += 1
            memo[u] = best; state[u] = 2
            return best
        ans = 0
        for i in range(n):
            got = dfs(i)
            if got is None:
                return -1
            ans = max(ans, max(got))
        return ans

